#!/usr/bin/env node
// Usage: node probe.mjs '<markdown source>'      -> prints exact ground-truth output with visible markers
//        node probe.mjs -f cases.json            -> JSON array of strings, prints each result
import { py } from './py.mjs';
import { readFileSync } from 'node:fs';

function show(s) {
  // Make trailing whitespace / newlines visible without altering the real bytes shown above.
  return JSON.stringify(s);
}

const argv = process.argv.slice(2);
let cases = [];
if (argv[0] === '-f') cases = JSON.parse(readFileSync(argv[1], 'utf8'));
else cases = [argv[0] ?? ''];

for (const c of cases) {
  const src = typeof c === 'string' ? c : c.a;
  const r = py(src);
  console.log('==== INPUT  ' + show(src));
  console.log('---- OUTPUT ' + show(r.stdout));
  console.log('---- RAW');
  process.stdout.write(r.stdout);
  console.log('---- rc=' + r.code + (r.stderr ? ' stderr=' + show(r.stderr) : ''));
  console.log('');
}

// Ground-truth probe: run the precompiled Python executable and capture exact bytes.
import { spawnSync } from 'node:child_process';

export const EXE = '/workspace/dataset/test2_executable';

export function py(a, b = 'x') {
  const r = spawnSync(EXE, ['--a', a, '--b', b], { encoding: 'buffer', maxBuffer: 1 << 28 });
  return {
    stdout: r.stdout ? r.stdout.toString('utf8') : '',
    stderr: r.stderr ? r.stderr.toString('utf8') : '',
    code: r.status,
  };
}

export function js(a, b = 'x', entry = '/output/test2.mjs') {
  const r = spawnSync(process.execPath, [entry, '--a', a, '--b', b], { encoding: 'buffer', maxBuffer: 1 << 28 });
  return {
    stdout: r.stdout ? r.stdout.toString('utf8') : '',
    stderr: r.stderr ? r.stderr.toString('utf8') : '',
    code: r.status,
  };
}
