#!/usr/bin/env node
// CLI probe: run the precompiled executable with an EXACT argv array (no shell involved).
// Usage: node cliprobe.mjs -f cases.json     where cases.json = JSON array of argv arrays
//                                           (or objects {argv:[...], note:"..."})
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test2_executable';

function show(s) { return JSON.stringify(s); }

const argv = process.argv.slice(2);
let cases = [];
if (argv[0] === '-f') cases = JSON.parse(readFileSync(argv[1], 'utf8'));
else cases = [argv];

for (const c of cases) {
  const args = Array.isArray(c) ? c : c.argv;
  const note = Array.isArray(c) ? '' : (c.note || '');
  const env = (!Array.isArray(c) && c.env) ? { ...process.env, ...c.env } : process.env;
  const r = spawnSync(EXE, args, { encoding: 'buffer', maxBuffer: 1 << 28, env });
  console.log('==== ARGV   ' + show(args) + (note ? '   # ' + note : ''));
  console.log('---- rc=' + r.status + (r.signal ? ' signal=' + r.signal : ''));
  console.log('---- OUT    ' + show(r.stdout ? r.stdout.toString('utf8') : ''));
  console.log('---- ERR    ' + show(r.stderr ? r.stderr.toString('utf8') : ''));
  console.log('');
}
